def AlphaNum_NumAlpha(s):
    alphabet = [chr(i) for i in range(ord('a'), ord('z') + 1)]
    alphabetnums = {letter: str(index + 1) for index, letter in enumerate(alphabet)}

    result = []
    i = 0
    while i < len(s):
        if s[i].isalpha():
            result.append(alphabetnums[s[i]])
        elif s[i].isdigit():
            num_str = ""
            while i < len(s) and s[i].isdigit():
                num_str += s[i]
                i += 1
            num_val = int(num_str)
            if 1 <= num_val <= 26:
                result.append(alphabet[num_val - 1])
            else:
                result.append(num_str)
            continue
        i += 1

    return "".join(result)
